// Emergency Medical Technician Practice Test 3. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–2.
import {q, mix} from './q.js';
const AAOS='Pollak (AAOS), Emergency Care and Transportation of the Sick and Injured', BRADY='Limmer & O’Keefe, Emergency Care', AHA='AHA BLS Provider Manual';
const ASSESS='Patient Assessment', BLS='Basic Life Support', TRAUMA='Trauma', MED='Medical Emergencies', PEDS='Pediatrics and Childbirth', ENV='Environmental Emergencies', SPEC='Special Situations';

export default {
 id:'emergency-medical-technician-3',
 event:'Emergency Medical Technician',
 title:'Practice Test 3',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'AAOS Emergency Care and Transportation of the Sick and Injured, Brady Emergency Care, and the AHA BLS Provider Manual',
 plan:[{area:ASSESS,weight:20},{area:BLS,weight:20},{area:TRAUMA,weight:16},{area:MED,weight:14},{area:PEDS,weight:16},{area:ENV,weight:10},{area:SPEC,weight:4}],
 questions:mix([
  q(ASSESS,'In DCAP-BTLS, what does the “P” stand for?','Punctures/penetrations',['Pulses and pressure','Pupils and pain','Pallor and paralysis'],'A','DCAP-BTLS lists injuries to look and feel for: deformities, contusions, abrasions and more.',AAOS),
  q(ASSESS,'What is the chief complaint?','The main reason the patient called',['The patient’s past surgeries','The EMT’s first impression','The final hospital diagnosis'],'B','It is best recorded in the patient’s own words, such as “My chest hurts.”',AAOS),
  q(ASSESS,'A chest pain patient says they have no trouble breathing. What is this finding called?','A pertinent negative',['A chief complaint','A vital sign','A sign of shock'],'C','Pertinent negatives are expected findings that are absent and help narrow the cause.',AAOS),
  q(ASSESS,'How often should a stable patient be reassessed during transport?','Every 15 minutes',['Every 30 seconds','Every 60 minutes','Only at the hospital'],'D','Unstable patients are reassessed every 5 minutes because they can change quickly.',AAOS),
  q(ASSESS,'For a medical patient, what does the EMT identify instead of a mechanism of injury?','Nature of illness',['Level of trauma','Point of impact','Speed of vehicle'],'A','The nature of illness is learned from the patient, family and scene clues.',AAOS),
  q(ASSESS,'In a noisy setting, how can a systolic blood pressure be estimated without a stethoscope?','By palpation at the radial pulse',['By looking at the skin color','By counting the breathing rate','By checking pupil size'],'B','The reading where the radial pulse returns is the approximate systolic pressure.',BRADY),
  q(ASSESS,'What is the lowest possible Glasgow Coma Scale score?','3',['0','1','5'],'C','Each of the three parts scores at least 1, so the range is 3 to 15.',AAOS),
  q(ASSESS,'Bluish skin around the lips and fingertips is called:','Cyanosis',['Jaundice','Pallor','Flushing'],'D','Cyanosis signals low oxygen in the blood and calls for prompt airway and breathing care.',AAOS),
  q(ASSESS,'Yellow skin and eyes most often suggest a problem with which organ?','Liver',['Lungs','Heart','Bladder'],'A','Jaundice comes from a buildup of bilirubin when the liver cannot clear it.',AAOS),
  q(ASSESS,'A patient sits leaning forward with hands on the knees to breathe. What is this position called?','Tripod position',['Fowler position','Recovery position','Trendelenburg position'],'B','Tripoding is a sign of respiratory distress as the patient uses extra muscles to breathe.',AAOS),
  q(BLS,'What is the recommended chest compression rate for adults?','100 to 120 per minute',['60 to 80 per minute','80 to 90 per minute','140 to 160 per minute'],'C','Compressing too fast lowers depth and lets the heart fill less between compressions.',AHA),
  q(BLS,'How deep should chest compressions be for an adult?','At least 2 inches, not over 2.4',['About 1 inch, no deeper','About half an inch only','At least 4 inches or deeper'],'D','Too shallow fails to move blood, and too deep raises the risk of injury.',AHA),
  q(BLS,'Why must rescuers allow full chest recoil after each compression?','So the heart can refill with blood',['To rest the rescuer’s arms','To check the pulse each time','To let the AED analyze'],'A','Leaning on the chest between compressions reduces blood flow to the heart and brain.',AHA),
  q(BLS,'How long should pauses in chest compressions be kept under?','10 seconds',['30 seconds','45 seconds','60 seconds'],'B','Minimizing interruptions keeps blood pressure up and improves survival.',AHA),
  q(BLS,'What is the compression-to-ventilation ratio for adult CPR?','30:2',['15:1','5:1','10:2'],'C','The same ratio is used for one or two rescuers when no advanced airway is in place.',AHA),
  q(BLS,'Which compression method is preferred for two-rescuer infant CPR?','Two-thumb encircling hands',['Heel of one hand','Two hands stacked','One finger on the sternum'],'D','Encircling hands give better depth and blood pressure than the two-finger method.',AHA),
  q(BLS,'A responsive infant is choking and cannot cry. What should the EMT do?','5 back slaps, then 5 chest thrusts',['Abdominal thrusts only','Blind finger sweeps','Hold the infant upside down'],'A','Abdominal thrusts are not used on infants because they can injure the liver.',AHA),
  q(BLS,'How long should each rescue breath last?','About 1 second',['About 3 seconds','About 5 seconds','About 10 seconds'],'B','Each breath should just make the chest rise; more air fills the stomach.',AHA),
  q(BLS,'A woman in late pregnancy is choking. What thrusts should be used?','Chest thrusts',['Abdominal thrusts','Back thrusts only','No thrusts at all'],'C','Chest thrusts avoid pressure on the uterus and baby while clearing the airway.',AHA),
  q(BLS,'Where are AED pads usually placed on an adult?','Right upper chest and left side',['Both on the middle of the back','Both on the abdomen','On the neck and upper arm'],'D','This position sends current through the heart; avoid placing pads over implanted devices.',AHA),
  q(TRAUMA,'A patient has an open wound to the chest that bubbles with breathing. What should be applied?','An occlusive dressing',['A dry gauze pad only','A tight elastic wrap','A cold pack'],'A','Sealing the wound keeps air from entering the chest; watch for signs of tension pneumothorax.',AAOS),
  q(TRAUMA,'Why may a full-thickness burn be painless?','Nerve endings are destroyed',['The skin is still intact','It is a minor burn','The patient is cold'],'B','Full-thickness burns often look white, leathery or charred and need specialist care.',AAOS),
  q(TRAUMA,'Using the adult rule of nines, what percentage is one entire leg?','18 percent',['9 percent','1 percent','36 percent'],'C','Each arm is 9 percent, and the front and back of the torso are 18 percent each.',AAOS),
  q(TRAUMA,'How should an amputated body part be cared for?','Wrap in sterile dressing, bag, keep cool',['Place it in a cup of ice water','Throw it out at the scene','Soak it in rubbing alcohol for transport'],'D','The bag should rest on ice, not in it, to avoid freezing damage.',AAOS),
  q(TRAUMA,'When splinting a long-bone fracture, what should the splint immobilize?','The joints above and below',['Only the fracture site','Only the joint below','Only the joint above'],'A','Check pulse, movement and sensation below the injury before and after splinting.',AAOS),
  q(TRAUMA,'Blood collecting in the chest cavity around the lung is called:','Hemothorax',['Pneumothorax','Hemoptysis','Hematuria'],'B','A large hemothorax can cause shock as well as breathing difficulty.',AAOS),
  q(TRAUMA,'How should an EMT position a conscious patient with a nosebleed and no spine injury?','Sitting and leaning forward',['Flat on the back','Head tilted far back','Face down on the floor'],'C','Leaning forward keeps blood out of the airway and stomach while pinching the nostrils.',AAOS),
  q(TRAUMA,'A patient has dry lime powder on the skin. What should the EMT do first?','Brush it off before flushing',['Flush with a little water','Rub it in with a towel','Cover it with an ointment'],'D','Water can react with some dry chemicals, so brush them off first, then flush.',AAOS),
  q(MED,'A patient with high blood sugar has deep, rapid breathing and fruity breath. What is this breathing called?','Kussmaul respirations',['Agonal respirations','Cheyne-Stokes breathing','Biot breathing'],'A','It is the body’s attempt to blow off acid in diabetic ketoacidosis.',AAOS),
  q(MED,'What is the usual adult dose of an epinephrine auto-injector?','0.3 mg',['3 mg','0.03 mg','30 mg'],'B','The pediatric auto-injector contains 0.15 mg for children who weigh less.',AAOS),
  q(MED,'Pain that begins near the navel and moves to the right lower quadrant suggests:','Appendicitis',['Gallstones','Heartburn','Kidney failure'],'C','A ruptured appendix can cause peritonitis, so prompt transport is important.',AAOS),
  q(MED,'Under medical direction, which agent may be given for certain swallowed poisons?','Activated charcoal',['Syrup of milk','Table salt solution','Ice water'],'D','Charcoal binds some poisons in the gut but is not used for acids, alkalis or petroleum.',AAOS),
  q(MED,'Chest pain that is relieved by rest and lasts only a few minutes is most consistent with:','Stable angina',['Heart attack','Pneumonia','Aortic rupture'],'A','Pain that continues at rest or does not improve suggests a heart attack instead.',AAOS),
  q(MED,'A heavy drinker who stopped two days ago is shaking, confused and seeing things. What is suspected?','Delirium tremens',['Heat stroke','Food allergy','Simple fainting'],'B','DTs are a life-threatening form of alcohol withdrawal that can lead to seizures.',AAOS),
  q(MED,'How often may an EMT help a patient take a nitroglycerin dose, if allowed?','Every 5 minutes, up to 3 doses',['Every 30 seconds, no limit','Once every hour only','Every 2 hours, up to 10 doses'],'C','Blood pressure must be checked before each dose because nitro can cause hypotension.',AAOS),
  q(PEDS,'A child has a barking, seal-like cough that is worse at night. What is suspected?','Croup',['Asthma','Pneumonia','Epiglottitis'],'D','Croup is a viral infection that narrows the airway below the vocal cords.',AAOS),
  q(PEDS,'What is a normal heart rate for a newborn?','About 120 to 160 per minute',['About 40 to 60 per minute','About 60 to 80 per minute','About 200 to 240 per minute'],'A','A newborn heart rate below 100 calls for ventilation support.',AAOS),
  q(PEDS,'During delivery, the amniotic fluid is greenish-brown. What does this indicate?','Meconium in the fluid',['Normal clear fluid','A full bladder','A healthy placenta'],'B','The baby may have been stressed and is at risk of breathing meconium into the lungs.',AAOS),
  q(PEDS,'The baby’s buttocks are the first part to appear. What is this called?','Breech presentation',['Cephalic presentation','Crowning','Limb presentation'],'C','Support the baby’s body and keep the airway clear if the head does not deliver quickly.',AAOS),
  q(PEDS,'During delivery, the umbilical cord is wrapped around the baby’s neck. What should the EMT do?','Gently slip it over the head',['Pull hard on the cord','Push the baby back in','Wait for the next contraction'],'D','If it cannot be loosened, clamp it in two places and cut between the clamps.',AAOS),
  q(PEDS,'A pregnant woman becomes dizzy while lying flat on her back. What should the EMT do?','Place her on her left side',['Raise her legs only','Sit her fully upright','Keep her flat and wait'],'A','The heavy uterus presses on the inferior vena cava and reduces blood return to the heart.',AAOS),
  q(PEDS,'A pregnant woman with high blood pressure and swelling has a seizure. What is suspected?','Eclampsia',['Hypoglycemia','Asthma','Placenta previa'],'B','Keep her on her left side, protect the airway and transport quickly.',AAOS),
  q(PEDS,'A previously healthy infant is found dead in the crib. What is the most likely cause?','Sudden infant death syndrome',['A broken arm from a fall','Food poisoning from formula','A bee sting allergy'],'D','Begin resuscitation unless there are obvious signs of death, and support the family.',AAOS),
  q(ENV,'Why should frostbitten feet not be rewarmed in the field if they might refreeze?','Refreezing causes worse damage',['Warmth always spreads infection','Frozen feet need no care','It speeds healing too much'],'A','Rewarming should start only when the patient can be kept warm afterward.',AAOS),
  q(ENV,'A patient is sweating, weak and dizzy in the heat but has normal mental status. What care is best?','Move to a cool place and rest',['Wrap in heavy wool blankets','Have them run laps in shade','Give them a hot drink'],'B','Remove extra clothing, give fluids if they can drink and watch for heat stroke signs.',AAOS),
  q(ENV,'A patient bitten by a black widow spider has severe muscle cramps in the abdomen. Why?','The venom affects the nerves',['It is a bacterial infection','It is a skin allergy only','It causes low blood sugar'],'C','Black widow venom is a neurotoxin that causes painful, board-like muscle rigidity.',AAOS),
  q(ENV,'A patient bitten on the hand by a rattlesnake is wearing rings. What should the EMT do?','Remove the rings promptly',['Cut and suck the wound','Apply ice to the bite','Apply a tight tourniquet'],'D','Swelling can make jewelry act like a tourniquet, so remove it before swelling starts.',AAOS),
  q(ENV,'Heat loss through sweating is mainly due to which process?','Evaporation',['Conduction','Radiation','Convection'],'A','Evaporation works poorly in high humidity, which raises heat illness risk.',AAOS),
  q(SPEC,'At a hazardous materials scene, where should the EMS treatment area be?','In the cold zone',['In the hot zone','In the warm zone','Inside the spill'],'B','The hot zone has the hazard, and the warm zone is used for decontamination.',AAOS),
  q(SPEC,'An adult in cardiac arrest has a valid, signed DNR order. What should the EMT do?','Follow the order and withhold CPR',['Start CPR anyway and transport','Call the police first and wait','Ignore all the paperwork'],'C','Comfort care should still be given; follow local protocols on verifying the order.',AAOS)
 ],7934)
};
